const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const [r1, c1, r2, c2] = line.trim().split(/\s+/).map(Number);

    // Rook
    let rookMoves;
    if (r1 === r2 || c1 === c2) {
        rookMoves = 1;
    } else {
        rookMoves = 2;
    }

    // Bishop
    let bishopMoves;
    const color1 = (r1 + c1) % 2;
    const color2 = (r2 + c2) % 2;
    if (color1 !== color2) {
        bishopMoves = 0;
    } else {
        if (Math.abs(r1 - r2) === Math.abs(c1 - c2)) {
            bishopMoves = 1;
        } else {
            bishopMoves = 2;
        }
    }

    // King
    const kingMoves = Math.max(Math.abs(r1 - r2), Math.abs(c1 - c2));

    console.log(`${rookMoves} ${bishopMoves} ${kingMoves}`);
    rl.close();
});
